CREATE FUNCTION public.pilot_settings_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.pilot_config IS DISTINCT FROM OLD.pilot_config AND current_setting('app.pilot_config_write',true) IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Use audited Master Admin pilot configuration';END IF;RETURN NEW;END $$;
CREATE TRIGGER pilot_settings_audit_guard BEFORE UPDATE ON public.trip_network_settings FOR EACH ROW EXECUTE FUNCTION public.pilot_settings_guard();
DO $migration$ DECLARE f text;BEGIN SELECT pg_get_functiondef('public.save_matching_pilot(jsonb,text)'::regprocedure) INTO f;f:=replace(f,'UPDATE public.trip_network_settings SET pilot_config','PERFORM set_config(''app.pilot_config_write'',''true'',true);UPDATE public.trip_network_settings SET pilot_config');f:=replace(f,'INSERT INTO public.account_security_audit','PERFORM set_config(''app.pilot_config_write'',''false'',true);INSERT INTO public.account_security_audit');EXECUTE f;
SELECT pg_get_functiondef('public.network_accept_offer(uuid,boolean)'::regprocedure) INTO f;f:=replace(f,'IF NOT d.pilot_wave',$guard$PERFORM 1 FROM public.workspaces WHERE id IN(d.source_workspace_id,o.provider_workspace_id) ORDER BY id FOR SHARE;PERFORM 1 FROM public.provider_network_profiles WHERE workspace_id=o.provider_workspace_id FOR SHARE;IF d.funding_required AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d.funding_versions) v WHERE v->>'funded'='true' AND (v->>'offerVersionAmountCents')::integer=o.amount_cents AND v->>'acceptedAt' IS NOT NULL) THEN RETURN jsonb_build_object('ok',false,'error','This offer is no longer available');END IF;IF NOT d.pilot_wave$guard$);EXECUTE f;END $migration$;
CREATE FUNCTION public.selected_trip_export(_ids uuid[],_columns text[],_format text) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE result jsonb;n integer;BEGIN IF auth.uid() IS NULL OR cardinality(_ids) NOT BETWEEN 1 AND 500 OR cardinality(_columns) NOT BETWEEN 1 AND 10 OR _format NOT IN ('csv','xlsx','pdf') OR EXISTS(SELECT 1 FROM unnest(_columns) x WHERE x NOT IN ('display_id','pickup_date','pickup_time','pickup_city','dropoff_city','status','transport_type')) THEN RAISE EXCEPTION 'Invalid selected export';END IF;
SELECT count(*),jsonb_agg((SELECT jsonb_object_agg(k,v) FROM jsonb_each(to_jsonb(t)) e(k,v) WHERE k=ANY(_columns)) ORDER BY t.pickup_date,t.pickup_time) INTO n,result FROM(SELECT id,display_id,pickup_date,pickup_time,pickup_city,dropoff_city,status,transport_type FROM public.trips WHERE id=ANY(_ids))t;
IF n<>(SELECT count(DISTINCT x) FROM unnest(_ids)x) THEN RAISE EXCEPTION 'Some selected trips are unavailable';END IF;
PERFORM public.record_selected_export(_ids,_columns,_format);RETURN coalesce(result,'[]'::jsonb);END $$;
CREATE FUNCTION public.record_selected_export(_ids uuid[],_columns text[],_format text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required';END IF;INSERT INTO public.account_security_audit(user_id,event_type,result,details) VALUES(auth.uid(),'selected_trip_export','prepared',jsonb_build_object('count',cardinality(_ids),'columns',_columns,'format',_format));END $$;
REVOKE ALL ON FUNCTION public.record_selected_export(uuid[],text[],text) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.selected_trip_export(uuid[],text[],text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.selected_trip_export(uuid[],text[],text) TO authenticated;